// ── SAT verifier: polynomial-time certificate checking ──────────
// Given a CNF formula and a truth assignment, verify in O(n)
function verifySAT(clauses, assignment) {
  // Each clause is an array of literals: positive int = variable,
  // negative int = negated variable. Variable i has value assignment[i].
  return clauses.every(clause =>
    clause.some(lit => {
      const varIdx = Math.abs(lit);
      const val    = assignment[varIdx];
      return lit > 0 ? val : !val;
    })
  );
}

// Formula: (x1 ∨ x2) ∧ (¬x1 ∨ x3) ∧ (¬x2 ∨ ¬x3)
const clauses = [[1, 2], [-1, 3], [-2, -3]];
// Verification is O(clauses × literals) — polynomial
console.log(verifySAT(clauses, { 1: true,  2: false, 3: true  })); // true
console.log(verifySAT(clauses, { 1: true,  2: true,  3: true  })); // false — (¬x2 ∨ ¬x3) fails
console.log(verifySAT(clauses, { 1: false, 2: false, 3: false })); // false — (¬x1 ∨ x3) fails

// ── SAT solver: exhaustive search — exponential O(2^n) ──────────
function solveSAT(clauses, numVars) {
  for (let mask = 0; mask < (1 << numVars); mask++) {
    const assignment = {};
    for (let i = 1; i <= numVars; i++) {
      assignment[i] = Boolean(mask & (1 << (i - 1)));
    }
    if (verifySAT(clauses, assignment)) return assignment;
  }
  return null; // unsatisfiable
}

const sol = solveSAT(clauses, 3);
console.log(sol); // { 1: true, 2: false, 3: true } or another valid assignment

// ── Subset Sum (NP-complete) — verifier vs. solver ──────────────
function verifySubsetSum(set, subset, target) {
  const included = subset.every(x => set.includes(x));
  const sum = subset.reduce((a, b) => a + b, 0);
  return included && sum === target;
}

// Verifier: O(n) — polynomial
console.log(verifySubsetSum([3, 1, 4, 1, 5, 9], [3, 4, 9], 16)); // true
console.log(verifySubsetSum([3, 1, 4, 1, 5, 9], [3, 4, 9], 17)); // false

// Solver: exponential — must try 2^n subsets
function solveSubsetSum(set, target) {
  const n = set.length;
  for (let mask = 0; mask < (1 << n); mask++) {
    let sum = 0;
    const subset = [];
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) { sum += set[i]; subset.push(set[i]); }
    }
    if (sum === target) return subset;
  }
  return null;
}
console.log(solveSubsetSum([3, 1, 4, 1, 5, 9], 16)); // [3, 4, 9]

// ── P vs NP implications ────────────────────────────────────────
// If P = NP:
//   - Every NP-complete problem (SAT, TSP, graph colouring) would be
//     solvable in polynomial time.
//   - Cryptography would collapse: RSA, ECC, and most public-key schemes
//     rely on the hardness of factoring/DLP — both believed NP-intermediate.
//   - Drug discovery, protein folding, scheduling optimisation: all tractable.
//
// If P ≠ NP (the expected case):
//   - NP-complete problems remain intractable for large inputs.
//   - Cryptography remains secure (assuming separation).
//   - We rely on approximation algorithms, heuristics, and special-case solvers.

// ── Coping with NP-completeness ──────────────────────────────────
// 1. Approximation algorithms: e.g., TSP with triangle inequality → 1.5× optimal
//    (Christofides algorithm). For Vertex Cover: 2-approximation in O(E).
// 2. Parameterised complexity: FPT (fixed-parameter tractable) algorithms
//    run in O(f(k) · nᶜ) where k is a small parameter.
// 3. Heuristics: genetic algorithms, simulated annealing, CDCL SAT solvers.
// 4. Special cases: TSP on planar graphs, 2-SAT (polynomial), 2-colouring.

// ── 2-SAT is in P — a polynomial tractable special case ──────────
// 2-SAT: each clause has exactly 2 literals.
// Reduce to strongly connected components (SCCs) in implication graph.
// SCC decomposition via Tarjan or Kosaraju is O(V+E) — polynomial.
